def next_vector(old, updates):
    result = []
    for j, oldbit in enumerate(old):
        choices = []
        for i in range(11):
            value = updates.get(i, oldbit)
            if isinstance(value, list):
                value = value[j]
            choices.append(value)
        result.append(b.select_by_state(states, choices, oldbit))
